const CE=(ch,title,description,loc,cast,tension,items=[])=>eventDefs.push({ch,title,description,loc,cast,tension,items})
CE(1,'The Man from Meung Steals the Letter','On his road from Gascony, d’Artagnan challenges a mocking stranger, is beaten by the man’s servants, and loses his introduction to de Tréville.','meung',[['dartagnan','Leaves Meung bruised, letterless, and determined to find the scarred stranger.'],['rochefort','Departs with the stolen introduction after reporting to Milady.']],4,['letter','sword'])
CE(2,'Three Musketeers Fill the Antechamber','At de Tréville’s headquarters, d’Artagnan observes Athos’s wound, Porthos’s display, and Aramis’s discreet court connections before his audience.','musketeers-lodging',[['dartagnan','Studies the celebrated company he hopes to join.'],['athos','Conceals pain beneath formal self-command.'],['porthos','Turns a splendid baldric into a performance of wealth.'],['aramis','Deflects teasing about a recovered handkerchief and his hidden patron.'],['de-treville','Commands a household whose rivalries mirror the court.']],2)
CE(3,'The Audience Is Interrupted','De Tréville receives d’Artagnan kindly, but the young Gascon sees the man from Meung through the window and rushes into the street.','musketeers-lodging',[['dartagnan','Abandons a promising audience to pursue his first enemy.'],['de-treville','Recognizes courage and inexperience in equal measure.'],['rochefort','Escapes before d’Artagnan can recover the stolen letter.']],3,['letter'])
CE(4,'Three Accidents Become Three Duels','While chasing Rochefort, d’Artagnan collides with Athos, exposes Porthos’s baldric, and compromises Aramis’s handkerchief, accepting three successive duels.','carmes',[['dartagnan','Answers embarrassment with three appointments to fight.'],['athos','Keeps the noon duel despite his reopened shoulder.'],['porthos','Challenges the stranger who discovered his display is only half complete.'],['aramis','Protects a lady’s secret by treating the handkerchief as an insult.']],4,['sword'])
CE(5,'The Intended Duel Becomes an Alliance','The Cardinal’s guards interrupt d’Artagnan’s duel with Athos; he joins Athos, Porthos, and Aramis against Jussac’s patrol.','carmes',[['dartagnan','Chooses the musketeers’ side and earns friendship through shared danger.'],['athos','Fights through his wound and accepts the Gascon as an ally.'],['porthos','Uses strength and bravado to hold the line.'],['aramis','Closes ranks with the companions.'],['jussac','Falls in a public defeat for the Cardinal’s guards.']],5,['sword'])
CE(6,'The King Rewards the Victors','De Tréville presents the affair to Louis XIII, who enjoys the Cardinal’s discomfort and rewards the four fighters after a second clash.','louvre',[['louis','Balances royal amusement against the need to avoid open conflict with Richelieu.'],['de-treville','Secures protection and reward for his men.'],['dartagnan','Receives royal notice without yet receiving a musketeer’s commission.'],['richelieu','Endures the King’s pleasure in his guards’ defeat.']],3)
CE(7,'The Four Households Form a Compact','D’Artagnan learns the companions’ habits, finances, and servants, hires Planchet, and turns prize money into a shared feast.','musketeers-lodging',[['dartagnan','Builds a household and begins living by the friends’ shared code.'],['athos','Offers judgment rather than material advice.'],['porthos','Recommends a servant and enjoys the feast.'],['aramis','Advises romance while guarding his own.'],['planchet','Enters service warily and begins proving indispensable.']],2)
CE(8,'Bonacieux Asks for Help','The draper Bonacieux reports his wife’s abduction and describes a scarred captor, drawing d’Artagnan into the Queen’s hidden struggle.','bonacieux-house',[['bonacieux','Seeks protection while revealing more than prudence allows.'],['dartagnan','Connects Constance’s abductor with his enemy from Meung.'],['rochefort','Emerges as the likely agent behind the seizure.']],3)
CE(9,'D’Artagnan Rescues Constance','D’Artagnan attacks the guards holding Constance and learns that her service to the Queen makes her a political target.','bonacieux-house',[['dartagnan','Turns curiosity into immediate loyalty to Constance.'],['constance','Escapes custody but remains responsible for the Queen’s urgent secret.'],['rochefort','Loses the prisoner while keeping the household under observation.']],5,['sword'])
CE(10,'The House Becomes a Mousetrap','D’Artagnan and the musketeers use the rooms above Bonacieux’s shop to watch the agents who return for Constance and anyone seeking her.','bonacieux-house',[['dartagnan','Waits above the trap, ready to protect Constance without understanding the whole plot.'],['bonacieux','Is arrested and begins yielding to the Cardinal’s pressure.'],['constance','Moves through her own home as hunted ground.'],['athos','Is mistakenly arrested when the police spring the trap.']],4)
CE(11,'Buckingham Enters Paris in Disguise','D’Artagnan follows Constance as she guides the disguised Duke of Buckingham to a secret meeting with Queen Anne.','louvre',[['constance','Carries Buckingham safely through watched streets and palace passages.'],['buckingham','Risks scandal and diplomacy to see the Queen.'],['dartagnan','Guards a meeting whose political scale now becomes clear.'],['anne','Prepares to receive the English duke in secrecy.']],4)
CE(12,'The Queen Gives Buckingham the Diamonds','Anne refuses Buckingham’s political hopes but gives him twelve diamond studs as a private token before he returns to England.','louvre',[['anne','Tries to contain a dangerous devotion while surrendering a compromising token.'],['buckingham','Treats the diamonds as proof that the Queen’s feeling survives refusal.'],['constance','Protects the meeting and its secret routes.']],4,['diamond'])
CE(13,'Bonacieux Is Recruited by Richelieu','Questioned at the Cardinal’s palace, Bonacieux trades loyalty for safety and money, agreeing to spy on his wife.','cardinal-palace',[['bonacieux','Accepts the Cardinal’s favour and turns informer against Constance.'],['richelieu','Converts a frightened husband into a useful household spy.'],['rochefort','Supplies the interrogation with details from the surveillance network.']],4)
CE(14,'The Man from Meung Watches Constance','Rochefort and the Cardinal’s agents close around Constance’s movements while d’Artagnan again recognizes the enemy who stole his letter.','luxembourg',[['dartagnan','Suppresses his old grievance long enough to protect Constance’s greater secret.'],['constance','Tries to preserve the Queen’s line of communication.'],['rochefort','Coordinates pursuit while remaining just beyond d’Artagnan’s reach.']],4,['letter'])
CE(15,'De Tréville Defends His Men','The conflict between royal musketeers and Cardinalist officials intensifies as arrests and accusations become a contest of influence.','musketeers-lodging',[['de-treville','Uses rank and directness to protect Athos and d’Artagnan.'],['richelieu','Lets legal officers apply pressure that soldiers alone cannot.'],['dartagnan','Learns that court protection matters as much as skill with a sword.'],['athos','Endures arrest without betraying the household’s secret.']],3)
CE(16,'Séguier Searches the Queen','Richelieu persuades Louis to let the chancellor search Anne’s private papers; the seized letter reveals her connection to Buckingham.','louvre',[['anne','Endures a humiliating search while trying to protect Buckingham.'],['louis','Allows jealousy to become an instrument of the Cardinal’s policy.'],['richelieu','Finds the evidence needed to design a public trap.']],5,['letter'])
CE(17,'The Cardinal Designs the Diamond Trap','Richelieu arranges a court ball and persuades the King to demand that Anne wear the studs, while Constance seeks a courier to England.','bonacieux-house',[['richelieu','Turns private correspondence into a timed public test.'],['anne','Faces disgrace unless the diamonds return from England.'],['constance','Chooses d’Artagnan for the dangerous recovery mission.'],['dartagnan','Accepts the Queen’s errand through his trust in Constance.'],['bonacieux','Reports his wife’s activity to the Cardinal’s side.']],5,['diamond'])
CE(18,'Love and Espionage Share a Household','D’Artagnan declares his devotion, Constance gives him the Queen’s authorization, and Bonacieux’s spying makes delay impossible.','bonacieux-house',[['dartagnan','Binds romantic hope to the duty of reaching Buckingham.'],['constance','Trusts d’Artagnan with the Queen’s honour while resisting promises she cannot yet make.'],['bonacieux','Mistakes betrayal for protection under Richelieu.']],4,['letter'])
CE(19,'The Friends Plan the English Mission','Athos, Porthos, and Aramis agree to accompany d’Artagnan to London, expecting ambushes along the northern road.','musketeers-lodging',[['dartagnan','Places the Queen’s mission inside the friends’ collective honour.'],['athos','Plans for sacrifice and secrecy rather than a clean journey.'],['porthos','Commits himself before equipment and cost are settled.'],['aramis','Chooses action despite the private life pulling him elsewhere.']],3,['letter','diamond'])
CE(20,'The Journey Breaks the Party Apart','Ambushes and provocations strand Porthos at Chantilly, Aramis at Crèvecœur, and Athos at Amiens; d’Artagnan and Planchet continue to Calais.','calais',[['dartagnan','Reaches Calais after refusing every delay that could ruin the Queen.'],['athos','Holds an inn cellar against attackers to protect the mission’s lead.'],['porthos','Stops at Chantilly with a wound and wounded pride.'],['aramis','Recovers at Crèvecœur while awaiting news from his hidden patron.'],['planchet','Keeps horses, papers, and practical decisions moving toward the Channel.']],5,['letter'])
CE(21,'D’Artagnan Crosses to England','After duelling and sparing Lord de Winter, d’Artagnan gains passage to London and an introduction to Milady.','buckingham-house',[['dartagnan','Turns a roadside enemy into the connection needed to reach Buckingham.'],['winter','Honours the man who spared him and opens his English household.'],['milady','Recognizes the Gascon as a possible instrument before he recognizes her danger.']],4,['sword'])
CE(22,'The Diamond Studs Return in Time','Buckingham discovers two studs missing, commissions exact replacements, and sends d’Artagnan racing back to the Louvre before the ballet.','louvre',[['buckingham','Spends influence and speed to repair the Queen’s jeopardy.'],['dartagnan','Delivers the complete set through a final chain of relays.'],['anne','Appears at the ballet with all twelve studs and defeats Richelieu’s exposure.'],['richelieu','Sees the public trap fail despite possessing the two stolen originals.'],['louis','Presents the recovered studs without understanding the counter-move.']],5,['diamond'])
CE(23,'The Queen Rewards D’Artagnan','After the ballet, Constance arranges a secret token of gratitude from Anne and promises d’Artagnan a rendezvous.','louvre',[['dartagnan','Receives the Queen’s ring but values Constance’s promised meeting more.'],['constance','Creates a private meeting despite the surveillance around her.'],['anne','Rewards a courier she cannot safely acknowledge in public.']],2,['queen-ring'])
CE(24,'Constance Is Taken from the Pavilion','D’Artagnan reaches the appointed pavilion too late and finds evidence that Constance has been abducted with Bonacieux’s cooperation.','luxembourg',[['dartagnan','Finds the rendezvous wrecked and turns hope into a new pursuit.'],['constance','Is removed before d’Artagnan can reach her.'],['bonacieux','Helps the Cardinal’s agents seize his own wife.'],['rochefort','Directs another disappearance without leaving d’Artagnan a target.']],5)
CE(25,'Porthos Recovers at Chantilly','D’Artagnan finds Porthos convalescing grandly and learns that campaign equipment depends on Madame Coquenard’s purse.','chantilly',[['porthos','Turns injury and debt into a performance designed for his patron.'],['dartagnan','Checks on his friend while gathering the scattered party.'],['coquenard','Weighs affection against the expense of Porthos’s ambitions.']],2)
CE(26,'Aramis Abandons His Thesis','At Crèvecœur, Aramis prepares to enter the Church until a coded letter and money from the Duchesse de Chevreuse restore his worldly prospects.','crevecoeur',[['aramis','Moves from theological resignation back toward friendship and intrigue.'],['dartagnan','Recognizes that discretion is the price of recovering his friend.'],['chevreuse','Reaches Aramis through a concealed message and renews his resources.']],2,['letter'])
CE(27,'Athos Tells the Story of His Wife','Freed from the Amiens cellar and made drunk, Athos recounts marrying a young woman whose fleur-de-lis brand revealed a criminal past.','amiens',[['athos','Exposes his deepest wound without yet knowing Milady and his wife are the same woman.'],['dartagnan','Receives a confession that will later explain Milady’s terror of Athos.']],4,['fleur'])
CE(28,'The Friends Return to Paris','The companions reunite, report the successful mission, and find that Constance has vanished beyond their immediate reach.','musketeers-lodging',[['dartagnan','Returns celebrated but unable to locate Constance.'],['athos','Resumes the group’s quiet centre after the cellar ordeal.'],['porthos','Rejoins with equipment still unresolved.'],['aramis','Returns with renewed money and guarded correspondence.'],['de-treville','Receives the four after a mission he cannot officially praise.']],3)
CE(29,'Campaign Equipment Becomes Urgent','Orders for La Rochelle force each friend to find horses, arms, and money without exposing the patrons behind their private lives.','musketeers-lodging',[['dartagnan','Measures royal reward against the practical cost of war.'],['athos','Refuses dependence while watching over the younger men.'],['porthos','Returns to Madame Coquenard’s promises.'],['aramis','Relies on a patron whose name remains concealed.']],2)
CE(30,'Milady Reappears in Paris','D’Artagnan sees Milady berating a man and follows her carriage, allowing fascination and suspicion to replace the lost trail to Constance.','luxembourg',[['dartagnan','Pursues Milady without understanding how closely she is tied to his enemies.'],['milady','Recognizes the persistent Gascon as both useful and dangerous.'],['rochefort','Remains connected to Milady’s movements through the Cardinal’s network.']],3)
CE(31,'D’Artagnan Duels Lord de Winter','A quarrel over Milady leads to a duel; d’Artagnan spares de Winter and is welcomed into Milady’s household.','luxembourg',[['dartagnan','Uses mercy to gain access to the woman he is investigating.'],['winter','Repays spared life with an introduction to his sister-in-law.'],['milady','Receives d’Artagnan politely while concealing her ties to Rochefort.']],4,['sword'])
CE(32,'Porthos Dines with the Coquenards','Porthos endures a miserly procurator’s dinner while persuading Madame Coquenard to finance the equipment his public image requires.','chantilly',[['porthos','Maintains magnificence through hunger and calculated charm.'],['coquenard','Commits money and hopes to a relationship built partly on display.']],2)
CE(33,'Kitty Opens Milady’s Letters','Kitty confesses love for d’Artagnan and shows him letters proving Milady desires the Comte de Wardes and hates him.','luxembourg',[['ketty','Risks her position by revealing her mistress’s correspondence.'],['dartagnan','Exploits Kitty’s trust to enter Milady’s private intrigue.'],['milady','Writes freely because she assumes her maid remains obedient.'],['de-wardes','Becomes the absent identity around which the deception is built.']],4,['letter'])
CE(34,'Aramis and Porthos Secure Their Outfits','Money from concealed patrons finally equips Aramis and Porthos for service, revealing how much their military lives depend on private arrangements.','musketeers-lodging',[['aramis','Accepts support without naming the Duchesse who sent it.'],['porthos','Converts Madame Coquenard’s reluctant generosity into visible splendour.'],['chevreuse','Sustains Aramis’s worldly future from exile.'],['coquenard','Finances Porthos while expecting lasting attention.']],2)
CE(35,'D’Artagnan Impersonates de Wardes','With Kitty’s help, d’Artagnan enters Milady’s darkened room under de Wardes’s name and accepts a sapphire ring.','luxembourg',[['dartagnan','Crosses from investigation into a cruel deception with dangerous consequences.'],['milady','Believes she has secured de Wardes’s devotion.'],['ketty','Enables the encounter despite knowing it will deepen her own hurt.'],['de-wardes','Has his identity used without his knowledge.']],4,['sapphire-ring'])
CE(36,'A Forged Rejection Provokes Milady','D’Artagnan sends Milady a false contemptuous letter in de Wardes’s name, then offers himself as the instrument of her revenge.','luxembourg',[['dartagnan','Turns jealousy into a trap while underestimating Milady’s capacity for retaliation.'],['milady','Redirects humiliation into a plan to have de Wardes killed.'],['ketty','Sees the deception move beyond her control.']],4,['letter'])
CE(37,'Milady’s Brand Is Revealed','D’Artagnan admits the impersonation; Milady attacks him, and her torn clothing exposes the fleur-de-lis that connects her to Athos’s story.','luxembourg',[['dartagnan','Escapes with certainty that Milady is Athos’s supposedly dead wife.'],['milady','Sees seduction, identity, and criminal history collapse into one exposure.'],['ketty','Helps d’Artagnan flee the household she can no longer safely remain in.']],5,['fleur','sword'])
CE(38,'Athos Converts the Sapphire into Equipment','D’Artagnan gives Athos Milady’s ring; Athos recognizes it, trades it for horses, and insists they prepare for the coming campaign.','musketeers-lodging',[['athos','Handles proof of his former marriage with cold practical purpose.'],['dartagnan','Gives up the compromised jewel and tells Athos the full encounter.']],3,['sapphire-ring'])
CE(39,'Two Letters Summon D’Artagnan','A hopeful note apparently from Constance and a formal summons from Richelieu pull d’Artagnan between private longing and state power.','cardinal-palace',[['dartagnan','Approaches the Cardinal while questioning whether either letter can be trusted.'],['richelieu','Receives the young man after studying his growing reputation.'],['constance','Remains absent while her name is used to command d’Artagnan’s hope.']],4,['letter'])
CE(40,'The Cardinal Offers Protection','Richelieu offers d’Artagnan advancement in exchange for allegiance; after he refuses, Milady points him out to hired attackers as the company leaves Paris.','paris-gate',[['richelieu','Tries recruitment before deciding how an independent adversary should be managed.'],['dartagnan','Refuses patronage that would divide him from the musketeers.'],['milady','Marks d’Artagnan for assassination as he departs for war.']],4)
CE(41,'Milady’s Assassins Strike at La Rochelle','During an exposed reconnaissance, d’Artagnan survives two hired killers and learns from the surviving attacker that Milady ordered his death.','camp',[['dartagnan','Survives the ambush and finally treats Milady as an active mortal threat.'],['milady','Reaches the siege through agents even while absent.'],['athos','Helps interpret the attack as part of a larger campaign against the four.']],5,['sword'])
CE(42,'The Anjou Wine Is Poisoned','A gift of wine supposedly sent by the friends kills a soldier who drinks it, proving Milady can reach d’Artagnan inside the royal camp.','camp',[['dartagnan','Recognizes that ordinary hospitality has become a weapon.'],['athos','Checks the bottle and message for the hand behind the attack.'],['porthos','Sees appetite turned into lethal risk.'],['aramis','Joins the decision to learn where Constance is held.'],['milady','Nearly kills d’Artagnan through a forged gift.']],5,['letter'])
CE(43,'The Cardinal Stops at the Red Dovecote','Richelieu orders Athos, Porthos, and Aramis to escort him to an inn, where he goes upstairs to meet an unidentified agent.','inn',[['richelieu','Uses the inn as a discreet operational meeting place.'],['athos','Recognizes an opportunity hidden inside an unwanted escort duty.'],['porthos','Waits below while watching the Cardinal’s movements.'],['aramis','Helps turn idle confinement into surveillance.']],3)
CE(44,'A Stovepipe Carries Milady’s Commission','The three musketeers overhear Richelieu order Milady to stop Buckingham and arrange d’Artagnan’s death; they also learn Constance is at Béthune.','inn',[['athos','Listens long enough to identify both the English danger and Constance’s refuge.'],['porthos','Keeps the innkeeper occupied while the secret is gathered.'],['aramis','Commits the details to memory for the coming warning.'],['richelieu','Authorizes violence while preserving political distance.'],['milady','Accepts the English mission and demands vengeance on d’Artagnan.']],5,['pass'])
CE(45,'Athos Takes the Cardinal’s Warrant','Athos confronts Milady alone, forces her to surrender Richelieu’s unrestricted pass, and warns that he knows her identity.','inn',[['athos','Uses recognition and a pistol to strip Milady of official protection.'],['milady','Loses the document that made private murder look like state service.']],5,['pass','fleur'])
CE(46,'The Four Breakfast in the Bastion','To discuss Milady beyond Richelieu’s hearing, the companions wager they can hold Bastion Saint-Gervais for an hour and carry breakfast under fire.','bastion',[['athos','Turns battlefield audacity into cover for a council.'],['dartagnan','Fights while absorbing the full danger to Buckingham and Constance.'],['porthos','Treats cannon fire as part of the wager and guards the meal.'],['aramis','Balances musket fire with plans for secret letters.'],['grimaud','Serves breakfast and ammunition with disciplined silence.']],5,['sword'])
CE(47,'The Council Sends Two Warnings','Inside the bastion, the friends decide to warn Lord de Winter and the Queen, finance their servants’ journeys, and keep the Cardinal’s pass in reserve.','bastion',[['dartagnan','Accepts promotion to the Musketeers after surviving the bastion.'],['athos','Coordinates warnings to England and Béthune.'],['porthos','Provides practical resources for the messengers.'],['aramis','Uses court and clerical contacts to conceal the letters.'],['planchet','Receives the dangerous English warning route.']],5,['letter','pass'])
CE(48,'The Servants Join the Family Affair','The four define the hunt for Milady as a private family matter, recruit their servants, and use the Queen’s ring to finance pursuit.','camp',[['athos','Uses the phrase “family affair” to keep Richelieu outside their plan.'],['dartagnan','Commits his royal reward to Constance’s rescue.'],['porthos','Brings the servants into the operational compact.'],['aramis','Builds the message network needed to find Milady.'],['planchet','Accepts responsibilities beyond ordinary service.']],3,['queen-ring'])
CE(49,'Lord de Winter Imprisons Milady','Forewarned by the musketeers, Lord de Winter confines Milady in his coastal castle under Felton’s guard.','winter-castle',[['milady','Studies the castle, timetable, and young officer for an escape route.'],['winter','Explains that Milady will be transported beyond England if she cannot manipulate her guards.'],['felton','Begins as a severe jailer convinced he is immune to the prisoner.']],4)
CE(50,'Brother and Sister Trade Threats','Lord de Winter confronts Milady with her past and his plans for exile, while she tests whether family pride can still intimidate him.','winter-castle',[['winter','Makes clear that he knows enough to prevent another inheritance crime.'],['milady','Abandons charm with de Winter and concentrates on Felton instead.']],4,['fleur'])
CE(51,'An Intercepted Letter Exposes Milady’s Reach','At La Rochelle, the friends intercept Milady’s message and use Grimaud’s discretion to keep the Cardinal from recovering it.','camp',[['athos','Secures the letter before Richelieu can connect it to their counter-plan.'],['dartagnan','Reads proof that Milady’s English captivity has not ended her influence.'],['grimaud','Conceals the document under direct pressure.'],['richelieu','Concludes that the four companions are too capable to ignore.']],4,['letter'])
CE(52,'Milady Chooses Felton','On the first day of captivity, Milady abandons direct escape attempts and decides that Felton’s severe faith can be turned against his commander.','winter-castle',[['milady','Recasts imprisonment as a study of one exploitable conscience.'],['felton','Maintains distance while becoming the centre of Milady’s attention.'],['winter','Believes the first day confirms the strength of his precautions.']],3)
CE(53,'Milady Performs Piety','On the second day, Milady uses prayer, song, and apparent resignation to disturb Felton’s certainty without openly asking for mercy.','winter-castle',[['milady','Builds a false spiritual identity tailored to Felton’s beliefs.'],['felton','Orders silence but carries the prisoner’s voice away with him.']],3)
CE(54,'Felton Begins to Believe','On the third day, Milady presents herself as a persecuted Protestant and lets Felton’s suspicion become protective sympathy.','winter-castle',[['milady','Makes Felton supply conviction where her evidence is weakest.'],['felton','Returns to the cell despite recognizing the danger of fascination.']],4)
CE(55,'A Feigned Suicide Wins an Oath','On the fourth day, Milady stages preparations for suicide, claims Buckingham persecuted her, and obtains Felton’s sworn help.','winter-castle',[['milady','Uses a false rope and blasphemous oath to turn sympathy into commitment.'],['felton','Promises rescue and begins treating murder as religious justice.']],5)
CE(56,'Milady Completes the False History','On the fifth day, Milady gives Felton a fabricated account of Buckingham’s abuse and allows his fanaticism to outrun her prompting.','winter-castle',[['milady','Calibrates every detail to leave Felton feeling he discovered the duty himself.'],['felton','Accepts the invented history as a command to punish Buckingham.']],5)
CE(57,'The Knife Deepens the Deception','Milady wounds herself when Lord de Winter interrupts, making the staged persecution appear physically real to Felton.','winter-castle',[['milady','Turns a controlled wound into final evidence for her chosen rescuer.'],['felton','Hides the knife and resolves to act before Milady is transported.'],['winter','Mistakes the wound for desperation rather than manipulation.']],5)
CE(58,'Felton Frees Milady','Felton lowers Milady from the castle window to a waiting ship; she promises to wait while he goes to confront Buckingham.','winter-castle',[['milady','Escapes and sets a rendezvous she has no intention of honouring.'],['felton','Abandons duty and carries the invented grievance toward Portsmouth.'],['winter','Discovers too late that the guard and prisoner have disappeared together.']],5)
CE(59,'Felton Assassinates Buckingham','At Portsmouth on 23 August 1628, Felton stabs Buckingham while Milady’s ship departs for France without him.','portsmouth',[['felton','Kills Buckingham and realizes the promised ship is already leaving.'],['buckingham','Dies while preparing the fleet intended to relieve La Rochelle.'],['milady','Watches England recede after obtaining the murder she was commissioned to cause.'],['winter','Arrives in time to understand both the assassination and Felton’s betrayal.']],5,['letter'])
CE(60,'The Musketeers Find the Armentières Clue','Back in France, the four learn that Milady has crossed the Channel; a discarded note in her hand sends them from Béthune toward Armentières.','bethune-convent',[['dartagnan','Rides for Constance with the fear that every hour benefits Milady.'],['athos','Turns fragments of handwriting into a route for the pursuit.'],['porthos','Keeps the group moving after the long siege campaign.'],['aramis','Connects convent intelligence with the recovered place-name.'],['rochefort','Passes the riders after carrying Milady’s report to Richelieu.']],4,['letter'])
CE(61,'Milady Befriends Constance at Béthune','At the Carmelite convent, Milady poses as another endangered ally and wins Constance’s confidence before Rochefort arrives.','bethune-convent',[['milady','Enters the refuge under a sympathetic identity and studies Constance’s hope.'],['constance','Welcomes the stranger without knowing she serves the force that separated her from d’Artagnan.'],['rochefort','Reaches Milady with the Cardinal’s latest instructions.']],5)
CE(62,'Milady and Rochefort Exchange News','Milady confirms Buckingham’s death, learns the musketeers are approaching, and sends Rochefort away while preparing her final revenge.','bethune-convent',[['milady','Chooses to remain long enough to destroy Constance before fleeing.'],['rochefort','Carries the successful assassination report toward Richelieu.'],['constance','Misreads the conspirators’ secrecy as evidence that Milady also needs rescue.']],5)
CE(63,'Milady Poisons Constance','Milady gives Constance poisoned wine and escapes moments before d’Artagnan and the musketeers arrive at the convent.','bethune-convent',[['constance','Dies at the moment reunion finally reaches her.'],['dartagnan','Arrives in time to hold Constance but not to save her.'],['milady','Converts retreat into one last personal victory.'],['athos','Contains grief long enough to organize pursuit.'],['winter','Joins the group with proof of Buckingham’s murder.']],5)
CE(64,'Athos Brings the Man in the Red Cloak','Athos summons the Lille executioner, whose ruined family gives the pursuit an additional witness and an appointed instrument of judgment.','armentieres',[['athos','Takes responsibility for assembling a tribunal outside ordinary law.'],['executioner','Answers the summons because Milady destroyed his sister and condemned him to punishment.'],['dartagnan','Follows while grief makes immediate vengeance feel inevitable.'],['winter','Adds Buckingham and his family to the charges.']],4)
CE(65,'The Witnesses Put Milady on Trial','At an isolated house near Armentières, Athos, d’Artagnan, the musketeers, de Winter, and the executioner enumerate Milady’s crimes.','armentieres',[['milady','Answers each witness with denial, contempt, and appeals to power.'],['athos','Names the marriage and branded identity he once concealed.'],['dartagnan','Accuses Milady of Constance’s poisoning and her attempts on his life.'],['winter','Charges her with Buckingham’s assassination and earlier family crimes.'],['executioner','Testifies to the destruction of his sister and his own unjust punishment.']],5,['fleur','pass'])
CE(66,'The Executioner Carries Out the Sentence','The Lille executioner takes Milady across the Lys, beheads her, and commits the body to the river before the companions return to Paris.','armentieres',[['milady','Meets the sentence after every identity and patron has failed to protect her.'],['executioner','Carries out the tribunal’s judgment and closes his family’s long pursuit.'],['athos','Accepts responsibility for the act without calling it triumph.'],['dartagnan','Finds that vengeance cannot restore Constance.'],['porthos','Stands with the group through the grim conclusion.'],['aramis','Witnesses a judgment beyond the institutions he once hoped to serve.']],5,['sword'])
CE(67,'Richelieu Confronts D’Artagnan','Rochefort arrests d’Artagnan, but Athos’s stolen pass makes Richelieu acknowledge Milady’s crimes instead of prosecuting the musketeers.','cardinal-palace',[['dartagnan','Faces the Cardinal without abandoning responsibility for Milady’s death.'],['richelieu','Accepts the signed authority as a political fact and chooses recruitment over revenge.'],['rochefort','Delivers the prisoner and watches an old enemy survive by the Cardinal’s own document.'],['athos','Places the pass in d’Artagnan’s hands as the friends’ final defence.']],4,['pass'])
CE(67,'D’Artagnan Accepts the Lieutenancy','Richelieu issues a blank lieutenant’s commission; Athos, Porthos, and Aramis refuse it in turn and insist that d’Artagnan take the promotion.','musketeers-lodging',[['dartagnan','Accepts command as the shared gift of the three men who made him their brother.'],['athos','Chooses retirement over rank and gives the future to d’Artagnan.'],['porthos','Turns toward marriage and prosperity without jealousy of the promotion.'],['aramis','Moves toward religious life while preserving affection for the group.'],['richelieu','Brings a formidable independent swordsman into royal service.']],3,['pass'])
const events=[],characterSnapshots=[]
const eventTime=(chapter,position)=>chapter<=40?90+(chapter-1)*2+position/10:chapter<=51?980+(chapter-41)*3+position/10:chapter<=58?1323+(chapter-52)+position/10:chapter===59?1330.5:chapter<=66?1331+(chapter-60)+position/10:1345+position/10
let previousWhen=null
eventDefs.forEach((e,index)=>{
 const eid=id('event',String(index+1).padStart(3,'0')), when=eventTime(e.ch,eventDefs.slice(0,index).filter(x=>x.ch===e.ch).length)
 const involved=e.cast.map(([s])=>C(s))
 const four=['dartagnan','athos','porthos','aramis'].filter(s=>e.cast.some(([c])=>c===s)).length
 const threadSlugs=[...(four>=2?['friendship']:[]),...(e.ch>=8&&e.ch<=24?['queen']:[]),...(e.ch>=30&&e.ch<=67?['milady']:[]),...(e.ch>=41&&e.ch<=60?['conquest']:[])]
 const motifSlugs=[...((e.items??[]).some(x=>['letter','pass'].includes(x))?['letters']:[]),...(/convent|house|palace|castle|captiv|prison|pavilion/i.test(`${e.title} ${e.description}`)?['doors']:[]),...((e.items??[]).includes('sword')||/duel|fight|bastion|battle|execution/i.test(`${e.title} ${e.description}`)?['duels']:[])]
 events.push({...base,id:eid,chapterId:chId(e.ch),timelineId,title:e.title,description:e.description,locationMarkerId:locId(e.loc),involvedCharacterIds:involved,mentionedCharacterIds:[],involvedItemIds:(e.items??[]).map(itemId),tags:[`chapter-${e.ch}`],threadIds:[...new Set(threadSlugs)].map(s=>id('thread',s)),motifIds:[...new Set(motifSlugs)].map(s=>id('motif',s)),sortOrder:events.filter(x=>x.chapterId===chId(e.ch)).length,travelDays:previousWhen===null?0:Math.max(0,Math.round((when-previousWhen)*10)/10),inWorldTime:when,tension:e.tension,structureBeat:null,status:'final',povCharacterId:involved[0]??null,isFlashback:false})
 previousWhen=when
 e.cast.forEach(([s,status],pos)=>characterSnapshots.push({...base,id:id('snapshot',`${String(index+1).padStart(3,'0')}-${s}`),characterId:C(s),eventId:eid,isAlive:!(s==='constance'&&e.ch>=63)&&!(s==='milady'&&e.ch>=66)&&!(s==='buckingham'&&e.ch>=59),currentLocationMarkerId:locId(e.loc),currentMapLayerId:locations.find(l=>l.id===locId(e.loc)).mapLayerId,inventoryItemIds:(s==='dartagnan'&&e.items?.includes('sword'))?[itemId('sword')]:[],inventoryNotes:'',travelModeId:null,sortKey:index*10000+pos,statusNotes:status}))
})

const plotThreads=[
 ['queen','The Queen’s Diamonds','A private English connection becomes Richelieu’s attempt to publicly compromise Anne of Austria.','#836145','resolved'],
 ['friendship','All for One','A chain of intended duels becomes an alliance whose loyalty repeatedly outweighs rank, money, and safety.','#596d74','resolved'],
 ['milady','Milady’s Counterattack','Milady’s private history and Cardinal’s commission turn political intrigue into a sequence of personal catastrophes.','#75505a','resolved'],
 ['conquest','The Siege of La Rochelle','The royal siege supplies the military pressure behind the novel’s court plots and English intervention.','#625e4e','resolved'],
].map(([s,name,description,color,status])=>({...base,id:id('thread',s),name,description,color,status,tags:[]}))
const motifs=[
 ['letters','Letters and Passes','Documents open doors, create obligations, and leave proof that power cannot fully erase.'],
 ['doors','Doors, Cells, and Convents','Private rooms are repeatedly turned into places of surveillance, confinement, and escape.'],
 ['duels','Duels and Codes','Formal honour gives way to a harder test: whether courage is used for one’s pride or another person.'],
].map(([s,name,description])=>({...base,id:id('motif',s),name,description,color:'#7a6554',tags:[]}))
